int main(void)
{
    InicializarReloj();     // F_CY = 40 MHz
    AD1PCFGL = 0xFFFF;      // todos los pines en digital
    PORTB = 0xFFFF;
    TRISB = 0x0FFF;                     // LEDs como salida
    PR1 = 0xFFFF;
    IFS0bits.T1IF = 0;
    T1CON = 0x30;                       // prescalado 255 y OFF
    while (1) {
        while ((PORTB & 0x4) == 0x4);   // espera a que RB2 baje a 0
        TMR1 = 0;
        IFS0bits.T1IF = 0;
        T1CON |= 0x8000;                // arranca el timer
        while ((PORTB & 0x4) == 0);     // espera a que RB2 vuelva a 1
        T1CON &= ~0x8000;               // para el timer (TON = 0)
        PORTB = ~TMR1;
    }
    return 0;
}

#include "config.h"

int act;

int main(void)
{
    InicializarReloj();     // F_CY = 40 MHz
    AD1PCFGL = 0xFFFF;      // todos los pines en digital
    PORTB = 0xFFFF;
    TRISB = 0x0FFF;                     // LEDs como salida
    PR1 = 40000;
    IFS0bits.T1IF = 0;
    IEC0bits.T1IE = 1;
    T1CON = 0x8000;                     // prescalado 0 y ON
    act = PORTB & 4;
    while (1);
    return 0;
}

int ant, tick = 0;

void __attribute__((interrupt, no_auto_psv)) _T1Interrupt(void)
{
    IFS0bits.T1IF = 0;
    ant = act;
    act = PORTB & 4;
    if (act == 0)
        tick++;
    else if (act != ant && act == 0x4) {
        PORTB = ~(tick << 12);
        tick = 0;
    }
}

