#include "config.h"

volatile unsigned int mseg = 0;     // contador de tiempo asíncrono: +1 cada 1 ms en la ISR
int estado_actual = 0;              // estado de la única máquina del sistema

void estado0(void)                  // reposo: D9 apagado, espera a que se pulse SW2
{
    if ((PORTB & 0x0004) == 0) {    // SW2 (RB2) pulsado = 0
        PORTB &= ~0x1000;           // enciende D9 (RB12, activo a nivel bajo)
        mseg = 0;                   // el evento pone a cero el contador (19.3)
        estado_actual = 1;
    }
}

void estado1(void)                  // D9 encendido durante 2 s
{
    if (mseg >= 2000) {
        PORTB |= 0x1000;            // apaga D9
        estado_actual = 0;
    }
}

void maquina(void)                  // una función por máquina de estados
{
    if (estado_actual == 0)
        estado0();
    else if (estado_actual == 1)
        estado1();
}

int main(void)
{
    InicializarReloj();
    AD1PCFGL = 0xFFFF;
    PORTB = 0xFFFF;                 // LEDs apagados
    TRISB = 0x0FFF;                 // RB12-RB15 (LEDs) como salidas
    PR1 = 40000;                    // 1 ms con pre-escalado 1:1
    TMR1 = 0;
    IFS0bits.T1IF = 0;
    IEC0bits.T1IE = 1;
    T1CON = 0x8000;
    while (1)
        maquina();
    return 0;
}

void __attribute__((interrupt, no_auto_psv)) _T1Interrupt(void)
{
    IFS0bits.T1IF = 0;
    mseg++;
}

#include "config.h"

void init_timer1(void);

unsigned int PER[6] = {20, 13, 40, 10, 20, 100};
unsigned int duracion[6] = {10000, 20000, 8000, 40000, 4000, 60000};
unsigned int cont = 0, periodos = 0, nota = 0;

int main(void)
{
    InicializarReloj();     // F_CY = 40 MHz
    AD1PCFGL = 0xFFFF;      // todos los pines en digital
    init_timer1();
    TRISB = 0;
    while (1);
    return 0;
}

void init_timer1(void)
{
    T1CON = 0x8000;
    PR1 = 2000;
    TMR1 = 0;
    IFS0bits.T1IF = 0;
    IEC0bits.T1IE = 1;
}

void __attribute__((interrupt, no_auto_psv)) _T1Interrupt(void)
{
    IFS0bits.T1IF = 0;                  // limpia el flag
    if (cont < PER[nota] / 2)
        PORTB |= 1;
    else
        PORTB &= ~1;
    cont++;
    if (cont >= PER[nota])
        cont = 0;
    periodos++;
    if (periodos >= duracion[nota]) {
        periodos = 0;
        cont = 0;
        nota++;
        if (nota > 5)
            nota = 0;
    }
}

static volatile int estado[3];          // static: no chocan con nombres del programa
static volatile int cont[3];
static int DC[3];                       // ancho del pulso en ticks de 0,5 ms
static int tick = 0;

void inicializa_driver_espantador()
{
    int servo;
    TRISB &= ~0x000E;                   // RB1-RB3 como salidas (servos 1-3)
    T1CON = 0x8000;                     // pre-escalado 1:1
    PR1 = 20000;                        // 20 000 · 25 ns = 0,5 ms
    TMR1 = 0;
    IFS0bits.T1IF = 0;
    IEC0bits.T1IE = 1;
    for (servo = 0; servo < 3; servo++)
        estado[servo] = 0;
}

void actua_servo(int servo)             // servo = 1, 2 o 3
{
    estado[servo - 1] = 1;
    cont[servo - 1] = 0;
}

void para_servo(int servo)              // servo = 1, 2 o 3
{
    estado[servo - 1] = 0;
}

static void maquina_servo(int servo)    // servo = 0, 1 o 2 (índice del array)
{
    cont[servo]++;
    if (estado[servo] == 0) {           // reposo: 0°
        DC[servo] = 3;
    } else if (estado[servo] == 1) {    // 90° durante 0,5 s
        DC[servo] = 5;
        if (cont[servo] > 1000) {
            estado[servo] = 2;
            cont[servo] = 0;
        }
    } else if (estado[servo] == 2) {    // −90° durante 0,5 s
        DC[servo] = 1;
        if (cont[servo] > 1000) {
            estado[servo] = 3;
            cont[servo] = 0;
        }
    } else if (estado[servo] == 3) {    // 0° durante 0,5 s
        DC[servo] = 3;
        if (cont[servo] > 1000) {
            estado[servo] = 4;
            cont[servo] = 0;
        }
    } else if (estado[servo] == 4) {    // 45° durante 0,25 s
        DC[servo] = 4;
        if (cont[servo] > 500) {
            estado[servo] = 5;
            cont[servo] = 0;
        }
    } else if (estado[servo] == 5) {    // −45° durante 0,25 s
        DC[servo] = 2;
        if (cont[servo] > 500) {
            estado[servo] = 6;
            cont[servo] = 0;
        }
    } else if (estado[servo] == 6) {    // 0° durante 0,25 s
        DC[servo] = 3;
        if (cont[servo] > 500) {
            estado[servo] = 1;          // la secuencia se repite
            cont[servo] = 0;
        }
    }
}

void __attribute__((interrupt, no_auto_psv)) _T1Interrupt(void)
{
    int servo;
    unsigned int salida;

    IFS0bits.T1IF = 0;                  // el flag del timer 1
    tick++;
    if (tick >= 40)                     // 40 · 0,5 ms = 20 ms (50 Hz)
        tick = 0;                       // tick recorre 0..39
    salida = PORTB;                     // regla RMW: se trabaja sobre una copia
    for (servo = 0; servo < 3; servo++) {
        maquina_servo(servo);
        if (tick < DC[servo])
            salida |= (1 << (servo + 1));       // servo 1 → RB1, 2 → RB2, 3 → RB3
        else
            salida &= ~(1 << (servo + 1));
    }
    PORTB = salida;                     // una sola escritura del puerto
}

#include "config.h"
#include "detectores.h"                 // get_medida() e inicializa_driver_detectores() (15.4.1)
void inicializa_driver_espantador(void);    // driver del espantador (19.6.2)
void actua_servo(int servo);
void para_servo(int servo);

#define DEC_ACTUA     50                // 50 · 0,1 s = 5 s
#define DEC_BLOQUEO  100                // 100 · 0,1 s = 10 s

volatile unsigned int decimas = 0;      // reloj del sistema: +1 cada 0,1 s

int servo_asoc1[3] = {1, 2, 3};
int servo_asoc2[3] = {3, 1, 2};
int bloqueado[3];                       // máquina de cada detector: 0 reposo, 1 bloqueado
unsigned int t_det[3];                  // instante de su última actuación
int activo[3];                          // máquina de cada espantador: 0 parado, 1 actuando
unsigned int t_esp[3];                  // instante en que se (re)arrancó

void arranca_espantador(int n, unsigned int ahora)     // n = 1, 2 o 3
{
    actua_servo(n);                     // (re)empieza la secuencia desde el paso 1
    activo[n - 1] = 1;
    t_esp[n - 1] = ahora;
}

int main(void)
{
    int det, esp, flanco;
    unsigned int ahora;

    InicializarReloj();
    AD1PCFGL = 0xFFFF;
    inicializa_driver_detectores();
    inicializa_driver_espantador();
    T2CON = 0x8030;                     // pre-escalado 1:256 (6,4 µs)
    PR2 = 15625;                        // 15 625 · 6,4 µs = 0,1 s
    TMR2 = 0;
    IFS0bits.T2IF = 0;
    IEC0bits.T2IE = 1;
    while (1) {
        ahora = decimas;                // 16 bits: se lee en una sola instrucción
        for (det = 0; det < 3; det++) {
            flanco = get_medida(det + 1);   // siempre: el driver guarda el valor anterior
            if (bloqueado[det] && ahora - t_det[det] >= DEC_BLOQUEO)
                bloqueado[det] = 0;
            if (!bloqueado[det] && flanco) {
                bloqueado[det] = 1;
                t_det[det] = ahora;
                arranca_espantador(servo_asoc1[det], ahora);
                arranca_espantador(servo_asoc2[det], ahora);
            }
        }
        for (esp = 0; esp < 3; esp++) {
            if (activo[esp] && ahora - t_esp[esp] >= DEC_ACTUA) {
                para_servo(esp + 1);
                activo[esp] = 0;
            }
        }
    }
}

void __attribute__((interrupt, no_auto_psv)) _T2Interrupt(void)
{
    IFS0bits.T2IF = 0;
    decimas++;
}
